 # Output: {'a.b': 1, 'a.c.d': 2, 'e': 3}

from collections import defaultdict
 def classify_chars(s):
  groups = defaultdict(int)
  for c in s:
  if c.isdigit(): groups['digits'] += 1
  elif c.isalpha(): groups['letters'] += 1
  elif c.isspace(): groups['spaces'] += 1
  else: groups['others'] += 1
  return dict(groups)

 print(classify_chars('Hello World! 42'))
 # Output: {'letters': 10, 'spaces': 2, 'others': 1, 'digits': 2}

def score_histogram(scores, bin_size=10):
  hist = {}
  for s in scores:
  key = (s // bin_size) * bin_size
  label = f'{key}-{key+bin_size-1}'
  hist[label] = hist.get(label, 0) + 1
  return dict(sorted(hist.items()))

 scores = [72,85,91,67,88,73,95,82,79,90]
 for rng, count in score_histogram(scores).items():
  print(f'{rng}: {"#"*count}')
 # Output: histogram buckets for each range

