# JavaScript Memoize Solution (Python demonstration)
 def memoize(fn):
  cache = {}
  def wrapper(*args):
  if args not in cache:
  cache[args] = fn(*args)
  return cache[args]
  return wrapper

 # JavaScript equivalent:
 # function memoize(fn) {
 # const cache = {};
 # return function(...args) {
 # const key = JSON.stringify(args);
 # if(!cache[key]) cache[key] = fn(...args);
 # return cache[key];
 # };
 # }

 def slow_square(n):
  # Simulate slow computation
  return n * n

 fast_square = memoize(slow_square)
 print(fast_square(5)) # 25 (computed)
 print(fast_square(5)) # 25 (from cache)
 print(fast_square(10)) # 100
 # Output:
 # 25
 # 25
 # 100

